inline constexpr int kProgressLimit = 2147483647;
struct Career { int rp=0; int xp=0; };
struct ProgressAward { int before=0; int after=0; int xp=0; int policy=0; };
struct ProgressPair { ProgressAward a; ProgressAward b; };

inline double expected_score(int a, int b) {
    return 1.0/(1.0+std::pow(10.0,(static_cast<double>(b)-static_cast<double>(a))/400.0));
}

inline int next_rating(int before, double score, double expected) {
    const auto delta=static_cast<int>(std::round(rating_k(before)*(score-expected)));
    const std::int64_t sum=static_cast<std::int64_t>(before)+delta;
    return static_cast<int>(std::clamp<std::int64_t>(sum,0,kProgressLimit));
}

inline ProgressPair progress_for(int a, int b, std::uint8_t winner) {
    if(a<0 || b<0)throw std::invalid_argument("negative rating");
    if(winner==study_net::MatchRecord::draw)return {{a,a,0,1},{b,b,0,1}};
    if(winner!=study_net::MatchRecord::a && winner!=study_net::MatchRecord::b)
        throw std::invalid_argument("invalid winner");
    const bool a_won=winner==study_net::MatchRecord::a;
    return {{a,next_rating(a,a_won?1.0:0.0,expected_score(a,b)),a_won?100:50,1},
            {b,next_rating(b,a_won?0.0:1.0,expected_score(b,a)),a_won?50:100,1}};
}

inline constexpr int kMaxLevel = 60;
inline constexpr int kBaseCost = 100;
inline constexpr int kCostStep = 20;

constexpr int bounded_level(int level) {
    return level < 1 ? 1 : (level > kMaxLevel ? kMaxLevel : level);
}

// Cumulative xp needed to reach a level (total_xp_for_level(1) == 0).
constexpr int total_xp_for_level(int level) {
    const int k = bounded_level(level) - 1;
    return kBaseCost * k + kCostStep * k * (k - 1) / 2;
}

// Xp needed to advance from a level to the next; 0 at max level.
constexpr int xp_to_next(int level) {
    const int l = bounded_level(level);
    return l == kMaxLevel ? 0 : kBaseCost + kCostStep * (l - 1);
}

inline int level_for_xp(int xp) {
    if (xp < 0) xp = 0;
    int level = 1;
    while (level < kMaxLevel && xp >= total_xp_for_level(level + 1))
        ++level;
    return level;
}

struct Progress {
    int level;  // current level, always 1..kMaxLevel
    int into;   // xp gained inside the current level
    int need;   // xp required to finish the current level
};

// Normalize xp, then report progress; at max level into/need are 0.
inline Progress progress(int xp) {
    if (xp < 0) xp = 0;
    const int level = level_for_xp(xp);
    if (level >= kMaxLevel) return {kMaxLevel, 0, 0};
    return {level, xp - total_xp_for_level(level), xp_to_next(level)};
}

inline constexpr const char* kProgressionSchema = R"sql(
CREATE TABLE careers (
  player_id TEXT PRIMARY KEY NOT NULL REFERENCES players(id) ON DELETE CASCADE,
  rp INTEGER NOT NULL DEFAULT 0 CHECK(typeof(rp)='integer' AND rp BETWEEN 0 AND 2147483647),
  xp INTEGER NOT NULL DEFAULT 0 CHECK(typeof(xp)='integer' AND xp BETWEEN 0 AND 2147483647)
);
CREATE TABLE match_progress (
  match_id INTEGER NOT NULL REFERENCES matches(id),
  player_id TEXT NOT NULL REFERENCES players(id),
  rp_before INTEGER NOT NULL CHECK(typeof(rp_before)='integer' AND rp_before BETWEEN 0 AND 2147483647),
  rp_after INTEGER NOT NULL CHECK(typeof(rp_after)='integer' AND rp_after BETWEEN 0 AND 2147483647),
  xp_delta INTEGER NOT NULL CHECK(typeof(xp_delta)='integer' AND xp_delta IN (0,50,100)),
  policy INTEGER NOT NULL CHECK(policy IN (0,1)),
  PRIMARY KEY(match_id,player_id)
);
)sql";

inline constexpr const char* kProgressionBackfill = R"sql(
INSERT INTO careers(player_id) SELECT id FROM players;
INSERT INTO match_progress(match_id,player_id,rp_before,rp_after,xp_delta,policy)
  SELECT id,player_a,0,0,0,0 FROM matches
  UNION ALL SELECT id,player_b,0,0,0,0 FROM matches;
)sql";

if(version==3) {
    db.exec(kProgressionSchema);
    db.exec(kProgressionBackfill);
    db.exec("INSERT INTO study_schema_history VALUES(4,'progression_v4');");
}

inline int add_xp(int before, int amount) {
    if(before<0 || amount<0 || amount>100 || before>kProgressLimit-amount)
        throw std::overflow_error("XP range exceeded");
    return before+amount;
}

Career read_career(std::uint64_t player) {
    Statement q(db_.get(),"SELECT rp,xp FROM careers WHERE player_id=?1");
    q.text(1,std::to_string(player));
    if(!q.next())throw std::runtime_error("career missing");
    const auto rp=q.integer_column(0), xp=q.integer_column(1);
    if(rp<0 || rp>kProgressLimit || xp<0 || xp>kProgressLimit)
        throw std::runtime_error("invalid career");
    return {static_cast<int>(rp),static_cast<int>(xp)};
}

const auto a=read_career(record.player_a), b=read_career(record.player_b);
const auto progress=progress_for(a.rp,b.rp,record.winner);
advance(row,record.player_a,a,progress.a);
if(hook)hook(RewardPoint::after_progress_a);
advance(row,record.player_b,b,progress.b);
if(hook)hook(RewardPoint::after_progress_b);
if(hook)hook(RewardPoint::before_commit);
transaction.commit();

void advance(sqlite3_int64 match, std::uint64_t player, Career before, ProgressAward award) {
    // put owns the write transaction and mutex throughout both participants.
    const int xp=add_xp(before.xp,award.xp);
    Statement q(db_.get(),"UPDATE careers SET rp=?1,xp=?2 WHERE player_id=?3");
    q.integer(1,award.after);q.integer(2,xp);q.text(3,std::to_string(player));q.done();
    if(sqlite3_changes(db_.get())!=1)throw std::runtime_error("career update missing");
    Statement receipt(db_.get(),"INSERT INTO match_progress VALUES(?1,?2,?3,?4,?5,?6)");
    receipt.integer(1,match);receipt.text(2,std::to_string(player));
    receipt.integer(3,award.before);receipt.integer(4,award.after);
    receipt.integer(5,award.xp);receipt.integer(6,award.policy);receipt.done();
}

if (const auto found = read_match(record.key)) {
    if (found->record != record)
        return {SqlStatus::conflict, {}};
    const auto saved=read_awards(record.key);
    if(!saved || !read_progress(record.key))throw std::runtime_error("saved receipt missing");
    return {SqlStatus::accepted,
            {record.key, found->row, record.player_a, record.player_b}, *saved};
}

int sum=0;
for(int level=1;level<=60;++level) {
    CHECK(levels::total_xp_for_level(level)==sum);
    CHECK(levels::level_for_xp(sum)==level);
    if(sum)CHECK(levels::level_for_xp(sum-1)==level-1);
    if(level<60){CHECK(levels::xp_to_next(level)==100+20*(level-1));sum+=100+20*(level-1);}
}
